It is clear that each weak proper $k$-coloring of $G$ is a weak proper $k$-coloring of $G_i$ for some $1 \le i \le m$.


Conversely, assuming $E(G) \ne \emptyset$, for any $1 \le i < j \le k$, there is some $uv \in E(G)$ such that $u
\to v$ in $G_i$ and $v \to u$ in $G_j$. This implies that there is no weak proper coloring that is a weak proper $k$-coloring of $G_i$ and~$G_j$.
If $E(G) = \emptyset$ then $G$ is the only orientation of itself.

\end{proof}

\begin{proof}[Proof of Theorem \ref{main}]
If $G$ is an acyclic mixed graph, then by Lemma \ref{phisum},
\begin{eqnarray*}
\chi_G(-k) &=& \displaystyle\sum_{i=1}^m \phi_{G_i}(-k) \\
&=& \displaystyle\sum_{i=1}^m \Omega_{P_i,\omega_i}(-k) \ \text{ (by Lemma \ref{labeling})}\\
&=& \displaystyle\sum_{i=1}^m (-1)^{|P_i|}\Omega_{P_i,\overline{\omega_i}}(k) \ \text{ (by Theorem \ref{stanley_op})}\\
&=& (-1)^{|V|}\displaystyle\sum_{i=1}^m \Omega_{P_i,\overline{\omega_i}}(k) \, . 
\end{eqnarray*}
By applying Lemma \ref{labeling} again, the proof is completed.
\end{proof}

\begin{proof}
Let $a=\vec{uv}$, $C$ be the set of weak proper $k$-colorings of $G$, and $C_a$ be the set of weak proper $k$-colorings of $G_a$. Therefore, $\chi_G(k) + \chi_{G_{a}}(k) = |C \cup C_a| + |C \cap C_a|$.

A coloring $c \in C \cup C_a$ if and only if $c$ is a weak proper $k$-coloring of $G-a$. A coloring $c \in C \cap C_a$ if and only if $c(u) = c(v)$ and $c$ corresponds to a weak proper $k$-coloring of $G/a$ in which the vertex created by identifying $u$ and $v$ is colored with $c(u)$. Therefore, $\chi_{G-a}(k) = |C \cup C_a|$ and $\chi_{G/a}(k) = |C \cap C_a|.$




\end{proof}

\begin{proof}
Fix $u \in V$, and let $c$ be a weak proper coloring of $G$. Since there is a directed path from $u$ to any $v$ and vice versa, $c(v) \le c(u) \le c(v)$ for every
$v \in V$. Therefore, $c(u) = c(v)$ for every $v \in V$, and since there are $k$ colors that can be assigned to $u$, $\chi_G(k) = k$.
\end{proof}

\begin{proof}
Let $s$ be the vertex that $S$ contracts to in $G/S$. For each weak proper $k$-coloring of $G$, the vertices of $S$ must all be colored the same color $j$. By defining $c(s) = j$ we get a bijection between the weak proper $k$-colorings of $G$ and $G/S$.
\end{proof}

\begin{proof}
Let $Q$ be a  linked system of quartet trees on a tree $T$ on a taxon set $X$. Linked systems are of size $n-3$ and each quartet tree distinguishes a unique edge in $T$. Let $T$ be a binary phylogenetic tree on a taxon set $X$ and let $e_1$ be an interior edge adjacent to a cherry. The tree is connected, which implies we can label the remaining interior edges $\{e_2, \cdots, e_{n-3} \}$ such that $e_j$ is adjacent to some $e_i$ with $i <j$. Moreover, because the support of each pair of quartet trees $\{q_i,q_j\}$ that distinguishes adjacent edges $\{e_i,e_j\}$ is five, each pair of quartet trees shares three taxa and each additional quartet tree in $Q$ adds one new taxon to the support of $Q$. Thus, linked systems meet the criteria in Proposition \ref{bocker2} and are definitive. 
\end{proof}

