anthropic_raw_latex:
\begin{proof}
Considering that $A$ is a simultaneous Volterra-Lyapunov stable matrix, the following inequality should be true:
\begin{equation}\label{eq_mdl}
[A]^m_{s_i} D + D ([A]^m_{s_i})^T  > 0. 
\end{equation}
Assume the total number of the $m_{th}$-order squared matrices $[A]^m_{s_i}$ is $N$, i.e., $i \in \{1,2, \cdots, N\}$. Based on inequality (\ref{eq_mdl}), we can conclude, for any $\gamma_i>0$, $i \in \{1, \cdots, N\}$, the following inequality holds
\begin{equation} \label{al_1}
\begin{aligned}
(\gamma_1 [A]^m_{s_1} + \gamma_2 [A]^m_{s_2} \cdots + \gamma_N [A]^m_{s_N})D & +\\
 D (\gamma_1 [A]^m_{s_1} + \gamma_2 [A]^m_{s_2} \cdots + \gamma_N [A]^m_{s_N})^T & >0
\end{aligned}
\end{equation}

Based on Lemma \ref{lemma2}, for any diagonal positive matrix $D > 0$ and $j \in \mathcal{M}$, we have
\begin{equation}\label{eq_important}
Re\{ \sigma [ (\sum_{i=1}^{N} \gamma_i  [A]^m_{s_i})  D]_j \} >0.
\end{equation}

Without loss of generality, we only consider the proof for the $m_{th}$-order matrices. So, we omit the
subscript $j$ in the following discussions.

According to structure of $K$, as before, we redefine the sub-indices of the $n$ columns of $A$ as follows: 
$$A=[\boldsymbol{a}_{1,1}, \cdots, \boldsymbol{a}_{1,p_1}, \boldsymbol{a}_{2,1}, \cdots, \boldsymbol{a}_{2,p_2}, \cdots, \cdots, \boldsymbol{a}_{m,1} \cdots,\boldsymbol{a}_{m,p_m}].$$ 

Correspondingly, we redefine the sub-indices of $\gamma_i>0$, $i \in \{1, \cdots, N\}$ in inequality (\ref{al_1}) as follows;
\begin{equation}
\gamma_{(\zeta_1, \zeta_2, \cdots, \zeta_m)},    
\end{equation}
where $\zeta_i \in \{1,2,\cdots,p_i\}$. The coefficient $\gamma_{(\zeta_1, \zeta_2, \cdots, \zeta_m)}$ means from each of the following group of vectors to select one vector to correspond to a term $\gamma_{(\zeta_1, \zeta_2, \cdots, \zeta_m)} [A]^m_{s_i}$ in inequality  (\ref{eq_important}):
\begin{equation}
\begin{aligned}
 Group\,1: & \,\,  \boldsymbol{a}_{1,1}, \cdots, \boldsymbol{a}_{1,p_1},\\ 
 Group\,2:  & \,\, \boldsymbol{a}_{2,1}, \cdots, \boldsymbol{a}_{2,p_2}, \\
  &\cdots, \cdots, \\
 Group\,m: & \,\, \boldsymbol{a}_{m,1} \cdots,\boldsymbol{a}_{m,p_m}. \\   
\end{aligned}
\end{equation}

Further assume $D=diag\{[d_1,d_2,\cdots, d_m]\}$.  Then the core part of the equation (\ref{eq_important}) can be expressed as follows:
\begin{equation} \label{carefu}
\begin{aligned}
     (\sum_{i=1}^{N} \gamma_i  [A]^m_{s_i})  D  
=[& d_1 ( \sum_{j=1}^{p_1} (\sum_{\zeta_2=1}^{p_2} \sum_{\zeta_3=1}^{p_3} \cdots \sum_{\zeta_m}^{p_m} \gamma_{( j, \zeta_2, \cdots, \zeta_m )} ) \boldsymbol{a}_{1,j} ), \\
     & d_2 ( \sum_{j=1}^{p_2} (\sum_{\zeta_1=1}^{p_1} \sum_{\zeta_3=1}^{p_3} \cdots \sum_{\zeta_m}^{p_m} \gamma_{( \zeta_1, j, \zeta_3, \cdots, \zeta_m )} ) \boldsymbol{a}_{2,j} ), \\
     & \cdots \cdots \cdots \\
      & d_m  ( \sum_{j=1}^{p_m} (\sum_{\zeta_1=1}^{p_1} \sum_{\zeta_2=1}^{p_2} \cdots \sum_{\zeta_{(m-1)}}^{p_{(m-1)}} \gamma_{( \zeta_1, \zeta_2, \cdots, \zeta_{(m-1)},j)} ) \boldsymbol{a}_{m,j} ) ].\\  
\end{aligned}
\end{equation}

On the other hand, the matrix $AEK$ can be expressed as 
\begin{equation}\label{eq_li_comb1}
\begin{aligned}
AEK &= [ \sum_{j=1}^{p_1} \varepsilon_{1j} k_{1j} \boldsymbol{a}_{1,j}, \sum_{j=1}^{p_2} \varepsilon_{2j} k_{2j} \boldsymbol{a}_{2,j}, \cdots, \sum_{j=1}^{p_m} \varepsilon_{mj} k_{mj} \boldsymbol{a}_{m,j}]\\
& = [ \sum_{j=1}^{p_1} \tilde {k}_{1j} \boldsymbol{a}_{1,j}, \sum_{j=1}^{p_2} \tilde {k}_{2j} \boldsymbol{a}_{2,j}, \cdots, \sum_{j=1}^{p_m} \tilde {k}_{mj} \boldsymbol{a}_{m,j}]\\
& = [ \tilde {k}_{11} \sum_{j=1}^{p_1} \frac{\tilde {k}_{1j}}{\tilde {k}_{11}}  \boldsymbol{a}_{1,j}, \tilde {k}_{21} \sum_{j=1}^{p_2} \frac{\tilde {k}_{2j}}{\tilde {k}_{21}}  \boldsymbol{a}_{2,j}, \cdots, \tilde {k}_{m1} \sum_{j=1}^{p_m} \frac{\tilde {k}_{mj}}{\tilde {k}_{m1}} \boldsymbol{a}_{m,j}]\\
& = [ \tilde {k}_{11} \sum_{j=1}^{p_1} \bar {k}_{1j} \boldsymbol{a}_{1,j}, \tilde {k}_{21} \sum_{j=1}^{p_2} \bar {k}_{2j} \boldsymbol{a}_{2,j}, \cdots, \tilde {k}_{m1} \sum_{j=1}^{p_m} \bar {k}_{mj} \boldsymbol{a}_{m,j}].\\
\end{aligned}
\end{equation}
In the above equation, $\tilde {k}_{ij} = \varepsilon_{i,j} k_{i,j} \ge 0$, and  $\bar {k}_{ij} = \frac{\tilde {k}_{i,j}}{\tilde {k}_{i,1}}$ (considering the case $\tilde {k}_{i,1} \ne 0$), which implies $\bar {k}_{i1}=1$.

Now, according to Lemma \ref{pailiezuhe_Lemma}, in Equation (\ref{carefu}), if we let $d_i = \tilde{k}_{i1}$ ($i \in \{1,2,\cdots,m\}$), and
\begin{equation}\label{sub_s}
\begin{cases}
\begin{aligned}
&\gamma_{(1, 1, \cdots, 1)} = 1 \\
&\gamma_{( \zeta_1, \zeta_2, \cdots, \zeta_{(i-1)}, j, \zeta_{(i+1)}, \cdots, \zeta_{m})} = \gamma_{( \zeta_1, \zeta_2, \cdots, \zeta_{(i-1)}, 1, \zeta_{(i+1)}, \cdots, \zeta_{m})} \bar{k}_{ij},
\end{aligned}
\end{cases}
\end{equation}
the left-hand side of Equation (\ref{carefu}) equals that of Equation (\ref{eq_li_comb1}). Thus, we can conclude, that for any non-negative diagonal matrices $E \in  \mathbb{R}^{n \times n}$, the inequality (\ref{suf_con_1}) is always satisfied.
\end{proof}

